// Fictional opponent pool for Career Mode -- kept fictional on purpose so no
// simulated win/loss ever gets attached to a real fighter's name.
// Fictional opponent names, generated by combining pools rather than being a
// fixed list. The old flat list of 30 names capped the division badly -- a
// career runs 20-30 fights, so you'd see the same handful over and over.
// These pools yield thousands of distinct combinations.
const OPP_FIRST = [
  "Rico", "Dmitri", "Sione", "Kenji", "Bram", "Ezra", "Tomas", "Nikolai", "Marcus", "Aatos",
  "Deshawn", "Emil", "Rafael", "Owen", "Yusuf", "Cael", "Tavita", "Igor", "Miles", "Andrei",
  "Hiro", "Cormac", "Bilal", "Casper", "Wade", "Kofi", "Petro", "Silas", "Ansel", "Nnamdi",
  "Damir", "Luca", "Mateo", "Junior", "Kaito", "Anton", "Diego", "Malik", "Teodor", "Joaquim",
  "Radek", "Elias", "Vahid", "Nico", "Tariq", "Bruno", "Sami", "Odin", "Rustam", "Felipe",
];

const OPP_LAST = [
  "Alves", "Volkanov", "Tuilagi", "Osato", "Voss", "Cole", "Reyes", "Sablin", "Webb", "Virtanen",
  "Price", "Kowalczyk", "Bautista", "Marsh", "Demir", "Whitlock", "Fonoti", "Petrenko", "Donnelly",
  "Molnar", "Sakata", "Boyle", "Ndiaye", "Lindqvist", "Halloran", "Amankwah", "Dvornik", "Reeve",
  "Krogh", "Eze", "Barros", "Nakamura", "Okafor", "Lindgren", "Mbeki", "Sorokin", "Cardoso",
  "Haddad", "Novak", "Ferreira", "Kimura", "Abadi", "Stroud", "Vasquez", "Ionescu", "Bergman",
];

const OPP_NICK = [
  "Longbone", "The Reef", "Southpaw", "Iron Gate", "Glass City", "The Chemist", "Blacktop",
  "Two Piece", "Timber", "The Anvil", "Cold Steel", "The Surgeon", "Nightshift", "Bad Intentions",
  "The Lighthouse", "Steel Trap", "The Undertow", "Quicksand", "The Freight Train", "Ghost",
];

// Draws a set of unique fighter names. Roughly a third get a nickname.
function generateOpponentNames(count, rng = Math.random) {
  const used = new Set();
  const out = [];
  let guard = 0;
  while (out.length < count && guard < count * 40) {
    guard++;
    const first = OPP_FIRST[Math.floor(rng() * OPP_FIRST.length)];
    const last = OPP_LAST[Math.floor(rng() * OPP_LAST.length)];
    const key = `${first} ${last}`;
    if (used.has(key)) continue;
    used.add(key);
    const nick = rng() < 0.33 ? OPP_NICK[Math.floor(rng() * OPP_NICK.length)] : null;
    out.push(nick ? `${first} ‘${nick}’ ${last}` : key);
  }
  return out;
}

// ---------- Real UFC fighter roster (draft phase) ----------
// Physical stats (height/reach, inches) are real. STRIKING/GRAPPLING/WRESTLING/
// CARDIO/POWER/CHIN/SPEED/IQ are game-style ratings built for this app (0-99),
// not official numbers from any specific published title. Entries tagged
// "(Late)" or "(early)" are separate career-stage variants of the same person.
function F(n, wc, era, ht, rc, STRIKING, GRAPPLING, WRESTLING, CARDIO, POWER, CHIN, SPEED, IQ) {
  return { n, wc, era, ht, rc, STRIKING, GRAPPLING, WRESTLING, CARDIO, POWER, CHIN, SPEED, IQ };
}

